def folder(x): return (M14 if x.number==216 else M15)/x.directory
def hierarchy(x): return ('Phase 6: Analytical Storage and Query Engines', 'Module 14: OLAP Internals and Analytical Engines') if x.number==216 else ('Phase 6: Analytical Storage and Query Engines','Module 15: File, Serialization and Open Table Formats')
def contract(x):
 t=(folder(x)/'note.md').read_text()
 z=(folder(x)/'after-note.md').read_text() if (folder(x)/'after-note.md').exists() else ''
 def g(k):
  m=re.search(rf'(?m)^\*\*{re.escape(k)}\.\*\*\s*(.+)$',t); return m.group(1).strip() if m else ''
 old=(g('Outcome'),g('Đánh giá'),g('Lab'),g('Pitfalls'),g('Self-study (2,4 giờ)'),g('Done when'))
 if all(old): return old
 def pick(text,label):
  m=re.search(rf'(?m)^\*\*{re.escape(label)}\.\*\*\s*(.+)$',text); return m.group(1).strip() if m else ''
 tasks=re.findall(r'(?m)^\*\*Nhiệm vụ\.\*\*\s*(.+)$',z)
 return (pick(t,'Năng lực cần chứng minh'),pick(z,'Cách đánh giá'),tasks[0].strip() if tasks else '',pick(z,'Lỗi cần chủ động loại trừ'),tasks[1].strip() if len(tasks)>1 else '',pick(t,'Điều kiện hoàn thành'))
def front(x):
 src='\n'.join(f'  - {s}' for s in x.sources)
 return f'''---\nnote_id: {x.note_id}\nnote_type: concept-deep-dive\nstatus: review\nlanguage: vi\ncreated: 2026-10-01\nlast_verified: 2026-10-01\neditorial_pass: humanized-v1\nprimary_question: {x.question}\nsource_ids:\n{src}\naliases: [{x.title}]\ntags: [wiki/database-systems, serialization, compatibility, decision]\nreference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}\n---\n'''
def deep(x):
 p=[front(x),f'# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n']
 for i,(h,b) in enumerate(x.core,1): p.append(f'\n## {i}. {h}\n\n{b}\n')
 p.append('\n## 7. Ma trận kiểm chứng từng mệnh đề\n\nMỗi claim cần fixture, versioned contract, counterexample và oracle ở đúng tầng. Parse/decode success, registry acceptance hoặc feature name không tự chứng minh semantic correctness.\n')
 for i,q in enumerate(x.probes,1): p.append(f'\n### 7.{i}. {q}\n\n**Mệnh đề cần kiểm.** {q}.\n\n**Protocol.** Khóa source/schema versions, producer-consumer path, configuration và canonical meaning. Chạy positive, boundary và negative fixtures; lưu raw bytes/files, hashes, logs, typed output và exact failing cell. Đổi một assumption rồi ghi reversal condition.\n\n**Bằng chứng đạt.** Kết quả structural và semantic được báo riêng, có independent oracle, repetitions khi đo performance, reviewer và limitation. Lab chưa chạy chỉ được ghi protocol, không ghi expected behavior như observation.\n')
 refs='\n'.join(f'{i}. [[{s}]]' for i,s in enumerate(x.source_links,1)); cov='\n'.join(f'| [[{s}]] | Normative rule, architecture boundary hoặc decision evidence | Đã đọc locator; không suy ngoài phạm vi |' for s in x.source_links)
 p.append(f'''\n## 8. Quy trình phản biện\n\n1. Tách syntax/wire, structural compatibility, generated API và business semantics.\n2. Ghi direction bằng writer–reader versions, không chỉ dùng nhãn backward/forward.\n3. Khóa canonical meaning và negative fixtures trước implementation.\n4. Giữ source bytes/schema fingerprints để tái hiện.\n5. Mọi default, cache, inference hoặc registry policy đều là explicit configuration.\n6. Viết rollout, rollback và reversal condition trước merge.\n\n## 9. Câu hỏi tự kiểm tra\n\n1. Identity nằm ở name, position, field number hay stable ID?\n2. Parser biết điều gì và application phải biết điều gì?\n3. Cell/version nào chưa được test?\n4. Decode sạch có thể sai nghĩa ở đâu?\n5. Intermediate system có làm mất thông tin không?\n6. Evidence nào mới là protocol?\n\n## 10. Giới hạn và điều chưa cho phép kết luận\n\n- Chưa chạy benchmark engine hoặc compatibility matrix bằng libraries/registry thật.\n- Specifications được kiểm ngày 2026-10-01; library, generated API và registry behavior cần pin version.\n- Curriculum matrices là synthesis; không gán nguyên văn cho một source.\n- Note giữ trạng thái `review` tới khi chủ dự án duyệt.\n\n## Reference\n\n{refs}\n\n## Source coverage\n\n| Source slice | Nội dung sử dụng | Trạng thái |\n|---|---|---|\n{cov}\n\n## Key takeaways\n\n- Structural success và semantic correctness là hai gates riêng.\n- Writer–reader direction, version history và exact fixtures phải hiện trong evidence.\n- Defaults, aliases, unknown fields và registry modes có scope cụ thể; không dùng như bảo đảm chung.\n- Chưa chạy lab thì note là giáo trình/protocol, chưa phải production certification.\n''')
 return ''.join(p)
def curriculum(x,k):
 o,a,l,p,h,d=contract(x); ph,mo=hierarchy(x); head=f'# {ph}\n# {mo}\n# Lesson {x.number}: {x.title}'; body=re.sub(r'^---\n.*?\n---\n','',k,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
 note=f'{head}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {o}\n\n**Điều kiện hoàn thành.** {d}\n\n{body}'
 after=f'{head}\n\n## Thực hành\n\n**Nhiệm vụ.** {l}\n\nChỉ dùng fixture tổng hợp và môi trường cô lập. Lưu schema/source hashes, versions, commands, raw bytes, outputs, logs và limitations.\n\n## Kiểm tra cuối bài\n\n1. Nêu identity và compatibility boundary trung tâm.\n2. Đưa một ca parse sạch nhưng sai nghĩa.\n3. Nêu counterexample đảo quyết định.\n4. Phân biệt configured intent với observed evidence.\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {a}\n\n**Điều kiện đạt.** {d}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {h}\n\n**Lỗi cần chủ động loại trừ.** {p}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n'
